using CertDesk.Common; using CertDesk.Models; using CertDesk.Services;
namespace CertDesk.Forms;
public partial class TokenEditForm:Form { public TokenDevice Token{get;} TextBox inv=new(){Width=260},model=new(){Width=260},sn=new(){Width=260},notes=new(){Width=260}; ComboBox type=new(){Width=160,DropDownStyle=ComboBoxStyle.DropDownList},status=new(){Width=160,DropDownStyle=ComboBoxStyle.DropDownList},holder=new(){Width=260,DropDownStyle=ComboBoxStyle.DropDownList}; DateTimePicker rec=new(); public TokenEditForm(TokenDevice? t=null){Token=t??new TokenDevice(); InitializeComponent(); Build(); Lists(); if(t!=null)LoadT();} void Build(){int y=15; void row(string l,Control c){Controls.Add(new Label{Text=l,Left=20,Top=y+3,Width=140});c.Left=170;c.Top=y;Controls.Add(c);y+=38;} row("Инвентарный номер",inv); row("Тип токена",type); row("Модель",model); row("Серийный номер",sn); row("Дата поступления",rec); row("Статус",status); row("Держатель",holder); row("Примечание",notes); var ok=new Button{Text="Сохранить",Left=170,Top=y+10}; var cancel=new Button{Text="Отмена",Left=290,Top=y+10,DialogResult=DialogResult.Cancel}; UiTheme.ApplyButtonStyle(ok); Controls.AddRange(new Control[]{ok,cancel}); ok.Click+=Save;} void Lists(){type.Items.AddRange(new object[]{"Rutoken","JaCarta","eToken","Other"});status.Items.AddRange(new object[]{"storage","issued","damaged","written_off"});holder.Items.Add(new ComboBoxItem{Text="Не указан"}); foreach(var e in EmployeeService.GetActive()) holder.Items.Add(new ComboBoxItem{Id=e.Id,Text=e.FullName}); type.SelectedIndex=0;status.SelectedIndex=0;holder.SelectedIndex=0;} void LoadT(){inv.Text=Token.InventoryNumber;type.Text=Token.TokenType;model.Text=Token.Model;sn.Text=Token.SerialNumber; if(Token.ReceivedAt.HasValue) rec.Value=Token.ReceivedAt.Value; status.Text=Token.Status; foreach(ComboBoxItem i in holder.Items) if(i.Id==Token.HolderId) holder.SelectedItem=i; notes.Text=Token.Notes;} void Save(object? _,EventArgs __){ if(string.IsNullOrWhiteSpace(inv.Text)||type.SelectedItem==null){MessageHelper.Error("Инвентарный номер и тип обязательны");return;} Token.InventoryNumber=inv.Text.Trim();Token.TokenType=type.Text;Token.Model=model.Text;Token.SerialNumber=sn.Text;Token.ReceivedAt=rec.Value;Token.Status=status.Text;Token.HolderId=((ComboBoxItem)holder.SelectedItem).Id;Token.Notes=notes.Text;DialogResult=DialogResult.OK;} }
